self = <test_mirror_generations.MirrorGenerationTests testMethod=test_command_options_preserve_script_pinning>
def test_command_options_preserve_script_pinning(self): """Option values must not hide code operands from the generation pin.""" harness = """ import os, sys from pathlib import Path import mirror_reader execvpe = os.execvpe def paused_exec(executable, command, env): print('SELECTED', file=sys.stderr, flush=True) assert sys.stdin.readline() == 'resume\n' execvpe(executable, command, env) mirror_reader.os.execvpe = paused_exec mirror_reader.run(Path(sys.argv[1]), sys.argv[2:]) """ node = shutil.which("node") node_commands = ( [] if node is None else [ [node, "--require", "./mirror/scripts/preload.cjs", "./mirror/scripts/options.cjs"], [node, "--require=./mirror/scripts/preload.cjs", "./mirror/scripts/options.cjs"], [ node, "--conditions", "custom", "-r", "./mirror/scripts/preload.cjs", "./mirror/scripts/options.cjs", ], ] ) commands = node_commands + [ ["/bin/bash", "-o", "pipefail", "./mirror/options.sh"], ["/bin/bash", "+o", "pipefail", "./mirror/options.sh"], ] for command in commands: with self.subTest(command=command):
def write_code(value): self.set_value(value) (self.snapshot / "scripts/preload.cjs").write_text( f"global.preloadValue = {value!r};
" ) (self.snapshot / "scripts/peer.cjs").write_text(f"exports.value = {value!r};
") (self.snapshot / "scripts/options.cjs").write_text( "const cp = require('node:child_process');
" "const child = cp.execFileSync(process.execPath, ['-e', " "'console.log(require(process.argv[1]).value)', " "require.resolve('./peer.cjs')], {encoding:'utf8'}).trim();
" f"console.log(JSON.stringify([{value!r}, global.preloadValue, " "require('./peer.cjs').value, child, process.argv.slice(2)]));
" ) (self.snapshot / "options.sh").write_text( f"printf '%s\n' {value}
" f"{sys.executable} -c 'import module, subprocess, sys; " "print(module.VALUE); print(subprocess.check_output([sys.executable, " '"-c", "import module; print(module.VALUE)"], text=True).strip())' + "'
" "printf '%s\n' "$1"
" )
write_code("old") self.publish() pinned = self.mirror.resolve() data = "mirror/ordinary-data.txt" reader = subprocess.Popen( [sys.executable, "-c", harness, str(self.mirror), *command, data], cwd=self.root, env=dict(os.environ, PYTHONPATH=str(MODULES)), stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, start_new_session=True, ) try: self.assertTrue(_readable(reader.stderr, 10), "reader did not select") self.assertEqual(reader.stderr.readline().strip(), "SELECTED") write_code("new") self.publish_with_deadline() output, error = reader.communicate("resume
", timeout=10) self.assertEqual(reader.returncode, 0, error) if command[0] == node: > self.assertEqual(json.loads(output), ["old"] * 4 + [[data]]) E AssertionError: Lists differ: ['new', 'old', 'new', 'new', ['mirror/ordinary-data.txt']] != ['old', 'old', 'old', 'old', ['mirror/ordinary-data.txt']] E E First differing element 0: E 'new' E 'old' E E - ['new', 'old', 'new', 'new', ['mirror/ordinary-data.txt']] E ? ------- ^^^ ^^^ E E + ['old', 'old', 'old', 'old', ['mirror/ordinary-data.txt']] E ? ^^^ ^^^ +++++++
